=== global-error ===
     1	"use client";
     2	
     3	import { useEffect, useState } from "react";
     4	import { isChunkLoadError, reloadForChunkErrorOnce } from "@/lib/chunk-error";
     5	
     6	// Catches errors in the root layout itself. Must render its own <html>/<body>
     7	// and cannot rely on globals.css, so styles are inline.
     8	export default function GlobalError({
     9	  error,
    10	  reset,
    11	}: {
    12	  error: Error & { digest?: string };
    13	  reset: () => void;
    14	}) {
    15	  const [reloading, setReloading] = useState(false);
    16	
    17	  useEffect(() => {
    18	    if (!isChunkLoadError(error)) return;
    19	    if (reloadForChunkErrorOnce()) setReloading(true);
    20	  }, [error]);
    21	
    22	  if (reloading) {
    23	    return (
    24	      <html lang="en">
    25	        <body style={{ margin: 0, minHeight: "100vh", display: "grid", placeItems: "center", background: "#070b16", color: "#94a2bc", fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif" }}>
    26	          <p style={{ fontSize: 14 }}>Updating…</p>
    27	        </body>
    28	      </html>
    29	    );
    30	  }
    31	
    32	  return (
    33	    <html lang="en">
    34	      <body
    35	        style={{
    36	          margin: 0,
    37	          minHeight: "100vh",
    38	          display: "grid",
    39	          placeItems: "center",
    40	          background: "#070b16",
    41	          color: "#e7ecf6",
    42	          fontFamily: "system-ui, -apple-system, Segoe UI, Roboto, sans-serif",
    43	          padding: "1rem",
    44	        }}
    45	      >
    46	        <div style={{ maxWidth: 420, textAlign: "center" }}>
    47	          <div style={{ fontSize: 40, marginBottom: 12 }}>⚠️</div>
    48	          <h1 style={{ fontSize: 22, margin: "0 0 8px" }}>Something went wrong</h1>
    49	          <p style={{ color: "#94a2bc", fontSize: 14, margin: "0 0 8px" }}>
    50	            A critical error occurred. Please try again.
    51	          </p>
    52	          {error?.digest && (
    53	            <p style={{ color: "#63718c", fontSize: 12, fontFamily: "monospace", margin: "0 0 20px" }}>
    54	              ref: {error.digest}
    55	            </p>
    56	          )}
    57	          <button
    58	            onClick={() => reset()}
    59	            style={{
    60	              background: "linear-gradient(100deg,#4b8bf5,#9a7cff)",
    61	              color: "white",
    62	              border: 0,
    63	              borderRadius: 10,
    64	              padding: "10px 20px",
    65	              fontWeight: 600,
    66	              cursor: "pointer",
    67	            }}
    68	          >
    69	            Try again
    70	          </button>
    71	        </div>
    72	      </body>
    73	    </html>
    74	  );
    75	}

