import re,sys,os,glob
roots=sys.argv[1:]
files=[]
for r in roots:
    if os.path.isfile(r): files.append(r)
    else:
        for dp,dn,fn in os.walk(r):
            for f in fn:
                if f.endswith('.tsx'): files.append(os.path.join(dp,f))
tot=0; bad=[]
for f in files:
    s=open(f).read()
    for m in re.finditer(r'<button\b(.*?)>(.*?)</button>', s, re.S):
        attrs, inner = m.group(1), m.group(2)
        # icon-only: inner has no visible text (only svg / spans w/o text / whitespace / jsx)
        txt=re.sub(r'<svg.*?</svg>','',inner,flags=re.S)
        txt=re.sub(r'\{/\*.*?\*/\}','',txt,flags=re.S)
        txt=re.sub(r'<[^>]+>','',txt)
        txt=re.sub(r'\{[^}]*\}','',txt).strip()
        # count as icon-only if raw inner contains <svg or an emoji-ish single char and no words
        if ('<svg' in inner or re.search(r'^\s*[^\w\s]{1,2}\s*$',inner)) and not re.search(r'[A-Za-z]{2,}',txt):
            tot+=1
            if 'aria-label' not in attrs and 'title=' not in attrs and 'aria-labelledby' not in attrs and 'sr-only' not in inner:
                line=s[:m.start()].count('\n')+1
                bad.append(f"{f}:{line}")
print("icon-only buttons:",tot,"unlabeled:",len(bad))
for b in bad: print("  ",b)
EOF
